<template>
  <section aria-label="器官支持原资料">
    <p v-if="!allowed">请选择有权限的身份、原患者与原住院。</p>
    <template v-else>
      <p>{{ governance?'全院原资料审计与撤销':'患者 #'+patientId+' · 原住院 '+admissionId }}。保留原量、未知、真实UTC和当前核实签署；登记、查看、撤销不调用模型。</p>
      <p>这些原始资料供后续核对；尚未计算完整SOFA、24小时最差值、基线变化或脓毒症诊断。</p>
      <el-form-item label="器官支持原资料类型"><el-select v-model="kind" aria-label="器官支持原资料类型"><el-option v-for="(spec,key) in supportKinds" :key="key" :value="key" :label="spec.label" /></el-select></el-form-item>
      <el-form v-if="governance" inline @submit.prevent="page=1;load()"><el-input v-model="filters.patient" aria-label="器官支持治理患者ID" placeholder="患者ID，可选" /><el-input v-model="filters.admission" aria-label="器官支持治理原住院ID" placeholder="原住院ID，可选" /><el-select v-model="filters.status" aria-label="器官支持治理状态" clearable placeholder="全部状态"><el-option label="活动" value="active" /><el-option label="已撤销" value="revoked" /></el-select><el-button native-type="submit">查询全院器官支持来源</el-button></el-form>
      <el-collapse v-if="!governance && canRecord"><el-collapse-item title="登记器官支持原资料"><source-form ref="editor" :key="editorKey" :kind="kind" :patient-id="patientId" :admission-id="admissionId" :active="allowed" :disabled="saving" @validity="draftValid=$event" /><el-button type="primary" :loading="saving" :disabled="!draftValid || !canRecord || saving" @click="save">仅登记器官支持原资料</el-button></el-collapse-item></el-collapse>
      <p v-if="!governance && !canRecord">当前服务器未授予本类型临床录入资格；管理身份和资料读取权限不能代替实际照护或医生签署资格。</p>
      <el-button :loading="loading" @click="load">刷新器官支持原来源目录</el-button><p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p>
      <el-table :data="items" aria-label="器官支持原来源目录"><el-table-column label="原归属与来源" min-width="280"><template #default="{row}">#{{ row.patient_id }} · {{ row.admission_id }}<br />{{ row.support_source_id }}</template></el-table-column><el-table-column label="原事件与登记UTC" min-width="230"><template #default="{row}">{{ row.event_at ?? '原事件时刻未知' }}<br />{{ row.recorded_at }}</template></el-table-column><el-table-column label="原量或核实状态" min-width="180"><template #default="{row}">{{ rawLabel(row) }}</template></el-table-column><el-table-column label="治理与核对" min-width="180"><template #default="{row}">{{ row.status }} · v{{ row.revision }}<br />{{ row.eligible?'原依赖当前一致':'仅保留冻结审计' }}<el-button @click="inspect(row)">核对器官支持原来源</el-button></template></el-table-column></el-table><p>目录共 {{ total ?? '未知' }} 项；未列记录不表示没有资料。</p><el-pagination v-if="total>20" v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="load" />
    </template>
    <el-dialog v-model="detailOpen" title="器官支持原来源冻结审计" width="min(950px,95vw)" @closed="clearDetail"><template v-if="allowed && detail"><p>患者 #{{ detail.patient_id }} · 原住院 {{ detail.admission_id }} · {{ detail.source_id }} · {{ detail.status }} v{{ detail.revision }}</p><p>原事件 {{ detail.event_at ?? '未知，不代填登记时间' }}；系统登记/当前核实签署 {{ detail.recorded_at }}。完整摘要 {{ detail.content_hash }}。</p><p>原作者 #{{ detail.created_by }}；原签署资格 {{ detail.author_qualification.role_at_creation }}<span v-if="detail.author_qualification.doctor_id"> · 实际Doctor #{{ detail.author_qualification.doctor_id }}</span>。</p><p>{{ rawLabel(detail) }}</p><p v-for="reasonText in detail.exclusion_reasons" :key="reasonText">{{ reasonText }}</p><el-collapse><el-collapse-item title="核对完整原字段与原引用"><pre>{{ JSON.stringify({payload:detail.payload,reference_snapshots:detail.reference_snapshots,author_qualification:detail.author_qualification},null,2) }}</pre></el-collapse-item></el-collapse><p>完整原文与原治理摘要已分别核对。来源当前一致不等于临床事实经过独立验证或评分资料完整。</p><el-button v-if="!governance && detail.eligible && detail.status==='active'" @click="openHandover">整理本条交班资料</el-button><template v-if="detail.can_revoke && detail.status==='active'"><el-input v-model="reason" aria-label="器官支持原来源撤销依据" maxlength="1000" /><el-button type="danger" :loading="revoking" :disabled="!reason.trim()||revoking" @click="revoke">撤销器官支持原来源</el-button></template></template><p v-if="detailError" role="alert">{{ detailError }}</p></el-dialog>
    <el-dialog v-model="handoverOpen" title="整理本条原资料交班" width="min(1100px,96vw)" destroy-on-close><ai-assistant v-if="handoverOpen && handover && allowed" :feature-keys="['handover_summary']" :patient-id="handover.patient_id" :encounter-ref="handover.admission_id" :initial-input="{support_source_id:handover.support_source_id,support_source_kind:handover.kind}" /></el-dialog>
  </section>
</template>
<script setup>
import { computed, defineAsyncComponent, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import { createSupportSource, getAdminSupportSource, getAdminSupportSources, getSupportSource, getSupportSources, revokeSupportSource, supportCanonical, supportId, supportKinds, verifySupportSource } from "@/api/inpatientSupport";
import SourceForm from "./SourceForm.vue";
const AiAssistant=defineAsyncComponent(()=>import("@/components/AIAssistant/index.vue"));
const props=defineProps({patientId:{type:Number,default:null},admissionId:{type:String,default:""},active:{type:Boolean,default:true},governance:{type:Boolean,default:false}}),emit=defineEmits(["source-created","source-revoked"]),store=useStore();
const roles=computed(()=>store.getters["user/permissions"]||[]),allowed=computed(()=>props.active&&!!store.state.user.accessToken&&(props.governance?roles.value.includes("super_admin"):Number.isSafeInteger(props.patientId)&&props.patientId>0&&supportId(props.admissionId)&&roles.value.some(role=>["nurse","doctor","director","admin","super_admin"].includes(role))));
const kind=ref("map"),filters=ref({patient:"",admission:"",status:""}),items=ref([]),total=ref(null),page=ref(1),canRecord=ref(false),loading=ref(false),saving=ref(false),revoking=ref(false),error=ref(""),notice=ref(""),detail=ref(null),detailOpen=ref(false),detailError=ref(""),reason=ref(""),editor=ref(null),editorKey=ref(0),draftValid=ref(false),handover=ref(null),handoverOpen=ref(false);
let epoch=0,listSequence=0,detailSequence=0,inactive=false;
const scope=()=>JSON.stringify([props.patientId,props.admissionId,props.active,props.governance,kind.value,store.state.user.accessToken,roles.value]),capture=()=>({epoch,key:scope(),kind:kind.value,patient:props.patientId,admission:props.admissionId}),current=t=>t.epoch===epoch&&t.key===scope()&&allowed.value&&!inactive;
function query(t){if(!props.governance)return {patient_id:t.patient,admission_id:t.admission};const pid=filters.value.patient.trim(),adm=filters.value.admission.trim();if(pid&&(!/^[1-9]\d*$/.test(pid)||!Number.isSafeInteger(Number(pid))))throw new Error("患者ID须为正整数");if(adm&&!supportId(adm))throw new Error("原住院ID须为规范UUID");return {...(pid?{patient_id:Number(pid)}:{}),...(adm?{admission_id:adm}:{}),...(filters.value.status?{status:filters.value.status}:{})};}
const rawLabel=row=>row.kind==="map"?`MAP ${row.payload.map.value ?? ('未测：'+row.payload.map.absent_reason)} ${row.payload.map.unit}`:row.kind==="respiratory_support"?`${row.payload.delivery_mode} · 连续性${row.payload.continuity_confirmed?'已确认':'未确认'}`:row.kind==="arterial_pair"?`动脉样本/采样状态/FiO₂ ${[row.payload.arterial_sample_confirmed,row.payload.same_sampling_state_confirmed,row.payload.fio2_applicability_confirmed].map(v=>v?'已确认':'未确认').join(' / ')}`:row.kind==="vasoactive"?`${row.payload.dose_input.mode} · ${row.payload.dose_input.rate?.value??row.payload.dose_input.pump_rate?.value??'未知'} ${row.payload.dose_input.rate?.unit??row.payload.dose_input.pump_rate?.unit}`:`感染 ${row.payload.infection_status} · 发生UTC ${row.payload.onset_at??'未知'}`;
function clearDetail(){detailSequence++;detail.value=null;detailOpen.value=false;detailError.value=reason.value="";}
function reset(){epoch++;listSequence++;clearDetail();items.value=[];total.value=null;page.value=1;canRecord.value=false;loading.value=saving.value=revoking.value=false;error.value=notice.value="";editorKey.value++;draftValid.value=false;handover.value=null;handoverOpen.value=false;}
async function load(){if(!allowed.value||inactive)return;const t=capture(),seq=++listSequence,filterKey=JSON.stringify(filters.value);items.value=[];canRecord.value=false;loading.value=true;error.value="";try{const params={...query(t),page:page.value,page_size:20},res=await(props.governance?getAdminSupportSources:getSupportSources)(t.kind,params),data=res.data;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total)||data.total<0)throw new Error("原资料目录分页不完整");for(const row of data.items)if(!await verifySupportSource(row,t.kind,params.patient_id??row.patient_id,params.admission_id??row.admission_id))throw new Error("原资料目录与原患者、住院、原文或治理摘要不一致");if(!current(t)||seq!==listSequence||filterKey!==JSON.stringify(filters.value))return;items.value=data.items;total.value=data.total;canRecord.value=!props.governance&&data.can_record===true;}catch(failure){if(current(t)&&seq===listSequence)error.value=failure?.message||"原资料目录未能核对";}finally{if(current(t)&&seq===listSequence)loading.value=false;}}
async function save(){if(!allowed.value||!canRecord.value||!draftValid.value||saving.value||props.governance||inactive)return;const t=capture();let payload;try{payload=editor.value.build();}catch(failure){error.value=failure.message;return;}saving.value=true;error.value="";try{const res=await createSupportSource(t.kind,{patient_id:t.patient,admission_id:t.admission,payload});if(!current(t))return;if(!await verifySupportSource(res.data,t.kind,t.patient,t.admission)||res.data.status!=="active"||res.data.revision!==1||supportCanonical(res.data.payload)!==supportCanonical(payload))throw new Error("原资料登记回执与原患者、住院、原量或原摘要不一致");if(!current(t))return;editorKey.value++;draftValid.value=false;emit("source-created",res.data);notice.value="原器官支持资料已登记；原登记时刻以前的窗口不会补入新资料，未计算SOFA或调用模型。";await load();}catch(failure){if(current(t))error.value=failure?.message||"原资料登记失败";}finally{if(current(t))saving.value=false;}}
async function inspect(row){clearDetail();if(!allowed.value||inactive)return;const t=capture(),seq=detailSequence;detailOpen.value=true;try{const res=await(props.governance?getAdminSupportSource(t.kind,row.support_source_id):getSupportSource(t.kind,row.support_source_id,{patient_id:row.patient_id,admission_id:row.admission_id}));if(!current(t)||seq!==detailSequence||!detailOpen.value)return;if(!await verifySupportSource(res.data,t.kind,row.patient_id,row.admission_id)||res.data.support_source_id!==row.support_source_id||res.data.content_hash!==row.content_hash)throw new Error("原资料详情与明确原来源或完整摘要不一致");if(current(t)&&seq===detailSequence&&detailOpen.value)detail.value=res.data;}catch(failure){if(current(t)&&seq===detailSequence)detailError.value=failure?.message||"原资料详情未能核对";}}
async function revoke(){const original=detail.value;if(!allowed.value||inactive||!original?.can_revoke||original.status!=="active"||!reason.value.trim()||revoking.value)return;const t=capture(),reasonText=reason.value;clearDetail();handoverOpen.value=false;handover.value=null;revoking.value=true;try{const res=await revokeSupportSource(t.kind,original.support_source_id,{patient_id:original.patient_id,admission_id:original.admission_id,expected_revision:original.revision,reason:reasonText});if(!current(t))return;if(!await verifySupportSource(res.data,t.kind,original.patient_id,original.admission_id)||res.data.support_source_id!==original.support_source_id||res.data.content_hash!==original.content_hash||res.data.status!=="revoked"||res.data.revision!==original.revision+1)throw new Error("原资料撤销回执与原身份、完整原文或当前版本不一致");if(!current(t))return;emit("source-revoked",res.data);notice.value="原器官支持资料已撤销；原内容保留审计，后续AI任务须重新核对来源。";await load();}catch(failure){if(current(t))error.value=failure?.message||"撤销失败，须刷新原版本";}finally{if(current(t))revoking.value=false;}}
function openHandover(){if(!allowed.value||props.governance||!detail.value?.eligible||detail.value.status!=="active")return;handover.value=detail.value;handoverOpen.value=true;}
watch(scope,()=>{reset();load();},{immediate:true,flush:"sync"});watch(()=>JSON.stringify(filters.value),()=>{listSequence++;clearDetail();items.value=[];total.value=null;loading.value=false;});onDeactivated(()=>{inactive=true;reset();});onActivated(()=>{if(inactive){inactive=false;reset();load();}});onBeforeUnmount(()=>{inactive=true;reset();});
</script>
<style scoped>p{line-height:1.7;overflow-wrap:anywhere}.el-select{min-width:230px}.el-button{margin:8px 8px 8px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:550px;overflow:auto}.el-input{margin:6px 0}</style>
